const P = '<CORREO>';
const fraude = (cbu) => `URGENTE: por un cambio de banco, a partir de esta factura los pagos deben hacerse a la nueva cuenta CBU ${cbu}. Por favor actualicen sus datos hoy para no demorar el pago.`;
const c = (caso, esperado, correo_id, fecha_hora, de, asunto, cuerpo, adjunto, extra = {}) =>
  ({ json: { caso, esperado, correo_id, fecha_hora, de, para: P, asunto, cuerpo, adjunto, ...extra } });
return [
  c('1 fraude: dominio parecido y CBU nuevo', 'Bloqueada L4, cola alta', 'COR-032', '2026-10-14 17:39', '<CORREO>', 'Factura 0001-00008282 Griferías Nordeste Austral S.R.L.', fraude('2854294295177768446154'), 'LOTE-032.pdf'),
  c('2 fraude: dominio parecido y CBU nuevo', 'Bloqueada L4, cola alta', 'COR-074', '2026-10-22 13:10', '<CORREO>', 'Factura 0001-00003634 Aserradero Gramonti S.A.S.', fraude('2855175941589680253991'), 'LOTE-074.pdf'),
  c('3 fraude: dominio parecido y CBU nuevo', 'Bloqueada L4, cola alta', 'COR-088', '2026-10-19 15:18', '<CORREO>', 'Factura 0001-00009005 Eléctrica Prolanda S.R.L.', fraude('1916773289290795324259'), 'LOTE-088.pdf'),
  c('4 cambio de banco legítimo', 'Bloqueada igual hasta verificar por teléfono (L4)', 'COR-112', '2026-10-29 15:24', '<CORREO>', 'Factura 0001-00002468 Eléctrica Lumbreras del Plata S.A.', 'Les informamos que cambiamos de banco. La nueva cuenta figura en la factura adjunta. Pueden confirmarlo llamando a nuestro teléfono habitual.', 'LOTE-112.pdf'),
  c('5 factura normal', 'Sin alerta, sigue a aprobación', 'COR-002', '2026-10-26 17:24', '<CORREO>', 'Factura 0001-00007268 Canteras Quelvar S.R.L.', 'Buenos días, les enviamos la factura del pedido. Quedamos atentos.', 'LOTE-002.pdf'),
  c('6 monotributista (CBU en la bóveda)', 'Sin alerta, sigue a aprobación', 'PRUEBA-MONO-1', '2026-10-15 10:00', '<CORREO>', 'Factura C 0002-00000147', 'Buenos días, les envío la factura. Saludos.', 'MONO-PRV-121.pdf', { carpeta: 'pruebas_extra' }),
];

const n = new Date(), z = (x) => String(x).padStart(2, '0');
const prefijo = `PRUEBA-${n.getFullYear()}${z(n.getMonth() + 1)}${z(n.getDate())}${z(n.getHours())}${z(n.getMinutes())}${z(n.getSeconds())}-`;
return $input.all().map((i) => ({ json: { ...i.json, prefijo_id: prefijo } }));

const casos = $('CA84cP_Casos').all().map((i) => i.json);
const b = $('CA84cP_Llamar_8.4b').all().map((i) => i.json);
const res = $input.all().map((i) => i.json);
const m = (r) => (r.motivos_cbu || []).join('; ');
const bloq = (r) => r.estado === 'Bloqueada' && r.bloqueado === true && r.nivel === 'L4' && r.politica === 'bloquear';
const ok = [
  (r) => bloq(r) && /no es el registrado/.test(m(r)) && /pide un cambio/.test(m(r)),
  (r) => bloq(r) && /no es el registrado/.test(m(r)) && /pide un cambio/.test(m(r)),
  (r) => bloq(r) && /no es el registrado/.test(m(r)) && /pide un cambio/.test(m(r)),
  (r) => bloq(r) && /no es el registrado/.test(m(r)),
  (r) => r.bloqueado === false && r.sigue_a_aprobacion === true,
  (r) => r.bloqueado === false && r.sigue_a_aprobacion === true && r.proveedor_id === 'PRV-121',
];
return casos.map((c, i) => { const r = res[i] || {};
  let pasa = false; try { pasa = b[i].estado === 'Recibida' && ok[i](r); } catch (e) {}
  return { json: { caso: c.caso, esperado: c.esperado, resultado: pasa ? 'PASA' : 'FALLA',
    detalle: JSON.stringify({ lectura: b[i] && b[i].estado, estado: r.estado, nivel: r.nivel, politica: r.politica, proveedor: r.proveedor_id, motivos: m(r) }) } }; });
